def _decimal_or_none(value):
    """Parse a provider decimal string; return None when unparseable."""
    if value is None or isinstance(value, bool):
        return None
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError, ArithmeticError):
        return None
    return result if result.is_finite() else None

def _decimal_or_none(value):
    """Bound compatibility decimals before parsing, sorting or fixed-point output.

    Canonical provider quantities are <1e30 with at most 24 decimal places;
    reconstructed ratios/percentages can approach 1e56 and have 12 places.
    Wider compatibility limits here bound allocation, not economic plausibility.
    """
    if type(value) not in (str, int, float, Decimal):
        return None
    if isinstance(value, int) and value.bit_length() > 266:
        return None
    if isinstance(value, Decimal):
        if not value.is_finite() or len(value.as_tuple().digits) > 128:
            return None
        text = str(value)
    else:
        text = str(value)
    if (len(text) > 128 or not re.fullmatch(
            r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]{1,4})?", text)):
        return None
    try:
        result = Decimal(text)
    except (InvalidOperation, ValueError, TypeError, ArithmeticError):
        return None
    if (not result.is_finite() or not -64 <= result.as_tuple().exponent <= 80
            or (result != 0 and result.adjusted() >= 80)):
        return None
    return result


def _exact_crowding_product(shares, days):
    """Keep compatibility-list ordering independent of ambient Decimal precision."""
    with localcontext() as context:
        context.prec = 256
        context.Emax = 999999
        context.Emin = -999999
        return shares * days
